#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.42.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.42.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.42.0.js').read_text()
SEARCH=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-knowledge-search-v1.js').read_text()
IK=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-integrated-knowledge-v1.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.42.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.42.0','0.41.0','Knowledge Search & Advanced Retrieval'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema-stable storage 35 / project 20 / export 20')
c(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['retrieval_only_release'] and not MAN['migration']['canonical_data_rewrite'],'schema-stable retrieval boundary')
c('/wp-json/sc-workspace/v1/knowledge-search-contract' in MAN['rest_routes'] and "'/knowledge-search-contract'" in PHP,'Knowledge Search REST contract')
c(MAN['knowledge_search_schema']=='sc-workspace-knowledge-search/1.0' and MAN['saved_search_schema']=='sc-workspace-saved-search/1.0','Knowledge Search schemas')
ks=MAN['knowledge_search']
c(ks['cross_project'] and ks['corpus']=='derived-integrated-knowledge-index','cross-project derived corpus')
c(ks['saved_searches']=='browser-local-preferences' and ks['max_saved_searches']==40,'local saved searches')
c(ks['ranking_reasons_visible'] and not ks['hidden_relevance_score'],'explainable relevance boundary')
c(not ks['semantic_embeddings'] and not ks['server_index'] and not ks['automatic_ai'],'no server index / embeddings / automatic AI')
# concrete runtime contracts
c(all(x in SEARCH for x in ('function normalizePrefs','function search(entries','function rank(entry','function related(target','function savedSearch(raw','same recorded source')),'advanced retrieval runtime')
c(all(x in PHP for x in ('data-scw-retrieval-subtype','data-scw-retrieval-tag','data-scw-retrieval-origin','data-scw-retrieval-provenance','data-scw-retrieval-sort','data-scw-saved-search')),'advanced retrieval presentation')
c('function knowledgeSearchApi()' in JS and 'loadSavedKnowledgeSearches' in JS and 'renderSavedKnowledgeSearches' in JS,'saved-search browser integration')
c('rank.reasons' in JS and 'data-scw-related-list' in JS,'visible ranking reasons and related navigation')
g=MAN['governance']; c(g['knowledge_search_derived_from_integrated_index'] and not g['knowledge_search_server_index'] and not g['knowledge_search_semantic_embeddings'],'derived search / no server or embedding index')
c(g['knowledge_search_ranking_reasons_visible'] and not g['knowledge_search_hidden_relevance_score'],'visible ranking reasons / no hidden score')
c(g['knowledge_search_saved_searches_local_only'] and not g['knowledge_search_saved_searches_mutate_projects'],'saved searches do not mutate projects')
c('function derive(state)' in IK and 'duplicatesCanonicalContent:false' in IK,'v0.40 Integrated Knowledge retained')
c('function areaForView(view)' in NAV and all(x in NAV for x in ("start:{label:'Start'","projects:{label:'Projects'","research:{label:'Research'","review:{label:'Review'","exchange:{label:'Exchange'")),'v0.41 unified navigation retained')
c('expectedRevision' in PORT and 'silentLastWriteWins:false' in PORT,'v0.38 conflict-safe notebook sync retained')
c(all(x in REVIEW for x in ('buildReview','buildReconciliation','shadowProvenanceDatabase:false')),'v0.39 Notebook Review & Provenance retained')
c((REG['public_version'],REG['previous_version'])==('0.42.0','0.41.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0420'" in REGPHP and 'LEGACY_PENDING_KEY_V0410' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.41.0.json').exists() and (ROOT/'history/workspace-product-record-v0.41.0.json').exists(),'v0.41 history preserved')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.42.0.json',ROOT/'registry/workspace-product-record-v0.42.0.json']
for p in files: json.loads(p.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.42.0 — Knowledge Search & Advanced Retrieval')
